INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "session", "executed_at", "findings_note", "harm_finding") VALUES (29, 'accessible-circulation-geometry', NULL, 'EN', 1, 'co1', 'intrinsic', 'co-produced participatory research with wheelchair users on experiences of building corridors doorways and level changes', '["TERM-048","TERM-016"]', 'consensus', 'scoping', NULL, 10, 10, 0, 'none', NULL, NULL, 0, 'session_2026-09-02-research-batch-05-circulation-icf', '2026-09-02 21:08', 'R1 pass leg 1 of 8. Yield was method papers and off-slug community mobility; no co-produced study of building circulation surfaced. Not absence of the topic - absence of this study design ON this topic.', 0);
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "session", "executed_at", "findings_note", "harm_finding") VALUES (30, 'accessible-circulation-geometry', NULL, 'EN', 1, 'co1', 'intrinsic', 'What do co-produced and participatory studies led by disabled people report about the experience of moving through building circulation routes - corridors, doorways, thresholds, ramps and vertical circulation?', '["TERM-048"]', 'scholar', 'scoping', NULL, 20, 14, 0, 'none', NULL, NULL, 0, 'session_2026-09-02-research-batch-05-circulation-icf', '2026-09-02 21:08', 'R1 leg 2. INDEX CAVEAT recorded by the retrieving agent: Scholar Gateway returned only Wiley-published items. That is a publisher-scoped index, not a field index, so its silence is not evidence of absence.', 0);
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "session", "executed_at", "findings_note", "harm_finding") VALUES (31, 'accessible-circulation-geometry', NULL, 'EN', 1, 'co1', 'intrinsic', '(photovoice OR participatory OR "co-design" OR "co-produced" OR "lived experience") AND (blind OR "visually impaired" OR "vision impairment" OR deafblind) AND (wayfinding OR navigation OR "built environment" OR indoor)', '["TERM-048"]', 'pubmed', 'scoping', NULL, 26, 10, 0, 'none', NULL, NULL, 0, 'session_2026-09-02-research-batch-05-circulation-icf', '2026-09-02 21:08', 'R14 QUERY-SHAPE FAILURE AND WRONG INDEX, kept as an empty. PubMed query_translation expanded blind to "blinded"[All Fields] OR "blinding"[All Fields] - RCT masking - returning Ethiopian SRH services and a vaccination RCT protocol. 1 of 10 on-topic. Blind-navigation work also lives in HCI and architecture venues PubMed does not index.', 0);
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "session", "executed_at", "findings_note", "harm_finding") VALUES (32, 'accessible-circulation-geometry', NULL, 'EN', 2, 'grey', 'intrinsic', 'disabled people''s organisation report barriers corridors doorways step-free routes inside buildings lived experience survey members', '["TERM-048","TERM-016"]', 'web', 'scoping', NULL, 9, 9, 2, 'none', NULL, NULL, 0, 'session_2026-09-02-research-batch-05-circulation-icf', '2026-09-02 21:08', 'R14 GENUINE ABSENCE OF THIS GENRE, not of the topic. Disabled people organisation output in this territory addresses supply and policy - waiting lists, wheelchair-home targets, housing-market assessment data gaps - not the demand a corridor places on a body. The two admissions attributed here are ACADEMIC sources the engine surfaced in answer to a DPO-targeted query; the DPO genre itself yielded nothing admissible. || CORRECTED 2026-09-02: R7 FILING GAP, closed. This search admitted REF-00975 (Goodwin 2022) and REF-00977, and its note recorded only the DPO-genre absence. Two harm findings from REF-00975 lived in the agonist brief and nowhere in the database. (a) HOUSING INADEQUACY: 71.0 percent of participants were living in housing that did not fully meet their accessibility needs (38.6 percent modified partly accessible plus 32.4 percent not built or modified accessible) against 27.5 percent in accessible housing; among those reporting a SEVERE mobility impairment 85.1 percent, and PROFOUND 59.6 percent, were in inaccessible housing (10.1002/ajs4.214, section 3.1 and Table 2, pp. 960-961). (b) EGRESS AND EMERGENCY-WORKER ACCESS: the paper treats emergency egress and access for emergency workers INTO the building as an accessible-design safety requirement, not a by-product of circulation width; and corridor geometry appears as a tenancy risk in participants'' own words - Participant 66, 18-24 with a profound limitation, asked simply ''To be able to move about within your own home without damaging walls.'' Both verified verbatim in the retained full text. R7 makes failure, harm and inadequacy first-class evidence; leaving them in a brief is the by-product treatment R7 forbids.', 1);
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "session", "executed_at", "findings_note", "harm_finding") VALUES (33, 'accessible-circulation-geometry', NULL, 'EN', 2, 'co2', 'intrinsic', '"occupational therapy" professional body practice guideline environmental assessment wheelchair access home modification dimensions evidence RCOT WFOT AOTA', '["TERM-048"]', 'web', 'scoping', NULL, 7, 7, 0, 'none', NULL, NULL, 0, 'session_2026-09-02-research-batch-05-circulation-icf', '2026-09-02 21:08', 'ZERO-YIELD, kept. The search engine itself concluded the results do not address detailed guidelines from RCOT, WFOT or AOTA, nor dimensional specifications.', 0);
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "session", "executed_at", "findings_note", "harm_finding") VALUES (34, 'accessible-circulation-geometry', NULL, 'EN', 2, 'co1', 'intrinsic', 'Euan''s Guide Access Survey disabled people venue accessibility findings report toilets steps entrances', '["TERM-048"]', 'web', 'scoping', NULL, 9, 9, 0, 'none', NULL, NULL, 0, 'session_2026-09-02-research-batch-05-circulation-icf', '2026-09-02 21:08', 'Disability-led source (Scottish charity SC045492) running a real annual access survey, so the genre is right. Two reasons nothing was admitted: the 2023 report URL returns HTML rather than the PDF (logged, 15580 B), and the survey content is predominantly information provision, toilets and staff attitude rather than circulation geometry. || CORRECTED 2026-09-02: The two reasons given here are both wrong, and neither was knowable from what had been retrieved. (1) The URL did not return HTML instead of a PDF; it returned a Page-not-found page. The live report is one hop from the homepage at /accesssurvey and was retrieved in full on the same day (f07d3924aaec6708.pdf, 3344268 B, 29 pp). (2) The claim that the survey is predominantly information provision, toilets and staff attitude rather than circulation geometry was written from that 404 and is false: the report most-cited barrier is could not get around the venue (lack of lifts, narrow corridors, too little space or poor layout) at 56 percent, ahead of entrance access at 41 percent (p.13). The 6000+ respondents figure recorded alongside it is also unsupported; the report states over 4400. Admitted as REF-00978 / ACG-09 under the re-retrieval search logged the same day. The batch one disability-led source was screened out on a characterisation no retrieved payload supported - CLAUDE.md 2(c), against a Co-1 source, which CRPD Art 4.3 and R1 make co-primary. || CORRECTED 2026-09-02: R15 applied to my own writing: the ranking as first recorded OVER-CLAIMED. Full option set of Q7 (p.13-14) is parking 64, could-not-get-around-the-venue 56, could-not-participate 45, could-not-get-into-the-venue 41, no-suitable-toilet 41, staff-attitudes 34, facilities-not-as-expected 32, environment-uncomfortable 28, no-accessible-transport 22, staff-unsure-of-equipment 15, other 8, no-alternative-formats 4. So circulation geometry is NOT the most-cited barrier in the survey: parking at 64 percent outranks it. The defensible claim is that it is the most-cited IN-BUILDING barrier and second overall, ahead of entrance access and of accessible toilets which tie at 41 percent. Corrected before this batch reached canonical.', 0);
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "session", "executed_at", "findings_note", "harm_finding") VALUES (35, 'accessible-circulation-geometry', NULL, 'EN', 2, 'co2', 'intrinsic', 'Royal College of Occupational Therapists practice guideline falls prevention older adults environmental hazards thresholds handrails level changes recommendations', '["TERM-022"]', 'web', 'scoping', NULL, 8, 8, 0, 'none', NULL, NULL, 0, 'session_2026-09-02-research-batch-05-circulation-icf', '2026-09-02 21:08', 'ZERO-YIELD for the guideline document, kept. R14 WRONG INDEX: RCOT practice guidelines are member-gated, so the web tier returns commentary about them and never their recommendation text.', 0);
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "session", "executed_at", "findings_note", "harm_finding") VALUES (36, 'accessible-circulation-geometry', NULL, 'EN', 2, 'co2', 'intrinsic', '"Occupational Therapy Practice Guidelines"[Title] AND (vision OR "low vision" OR mobility OR "home modification" OR aging)', '["TERM-048"]', 'pubmed', 'scoping', NULL, 5, 5, 0, 'none', NULL, NULL, 0, 'session_2026-09-02-research-batch-05-circulation-icf', '2026-09-02 21:08', 'R14 GENUINE ABSENCE and it is a finding rather than a search artefact. All five retrieved and read at abstract level across three professional bodies and two independent search paths: the OT professional-body guideline literature carries no environmental-parameter content. The Co-2 negative is structural.', 0);
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "session", "executed_at", "findings_note", "harm_finding") VALUES (37, 'accessible-circulation-geometry', NULL, 'EN', 1, 'clinical', 'intrinsic', '(wheelchair propulsion) AND (ramp OR slope OR incline OR gradient) AND (shoulder OR kinetics OR kinematics OR "muscle activity" OR "mechanical efficiency")', '["TERM-001","TERM-016"]', 'pubmed', 'scoping', NULL, 91, 30, 2, 'none', NULL, NULL, 0, 'session_2026-09-02-research-batch-05-circulation-icf', '2026-09-02 21:08', 'Rich literature, the opposite of absence: 91 found. Yielded the two ramp-biomechanics admissions.  R7 HARM FINDING: Ramp descent is a higher shoulder-load event than fast propulsion, and the published discourse is almost entirely about ascent. || CORRECTED 2026-09-02: SECOND HARM FINDING ON THIS SEARCH, and a published error in a source the field will cite. Marchiori, Gagnon and Pradon 2023 (10.3390/s23218659, REF-00973) section 2.2 Protocol p.4 reads: ''the four treadmill slopes: 0, 2.7, 3.6 and 4.8 degrees. The four slopes greater than 0 corresponded to slopes that increase from one unit of height to 20, 16, 12 and 8 units of length, respectively.'' There are THREE slopes greater than zero, and four ratios are listed for them. The arithmetic settles the mapping: arctan(1/20)=2.86, arctan(1/16)=3.58, arctan(1/12)=4.76 degrees, matching 2.7, 3.6 and 4.8 to 1:20, 1:16 and 1:12. 1:8 is 7.13 degrees and WAS NOT TESTED. Anyone citing this paper for a 1:8 result would be citing an error in the paper itself. Record the mapping, not the sentence. THE SUBSTANTIVE HARM FINDING it carries: the shoulder-load penalty is incurred by the EXISTENCE of a slope, not by its steepness - shoulder flexion/extension push-phase HIGH risk goes 12.2 percent at level, then 44.5, 47.0, 45.2 percent across 1:20, 1:16, 1:12 (Table 3, pp. 7-8), and the authors'' own reading is that ''greater efforts are required to propulse the wheelchair from the smallest slope (2.7 degrees), but that this effort does not increase further with the increasing slope'' (section 4, p.11). Making a gradient shallower across the regulated range did not recover joint load in this study.', 1);
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "session", "executed_at", "findings_note", "harm_finding") VALUES (38, 'accessible-circulation-geometry', NULL, 'EN', 1, 'clinical', 'intrinsic', 'anthropometry of wheeled mobility device users clear floor area and turning space requirements in the built environment', '["TERM-003","TERM-062"]', 'consensus', 'scoping', NULL, 9, 9, 2, 'none', NULL, NULL, 0, 'session_2026-09-02-research-batch-05-circulation-icf', '2026-09-02 21:08', 'Yielded the Toronto Rehab mobility-scooter programme, both parts.  R7 HARM FINDING: No tested mobility scooter could complete all indoor manoeuvres within standard-allowed space, and the 1.5 m turning circle is a manual-wheelchair artefact that undersizes scooters by up to 223 percent.', 1);
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "session", "executed_at", "findings_note", "harm_finding") VALUES (39, 'accessible-circulation-geometry', NULL, 'DE', 1, 'clinical', 'intrinsic', 'Bewegungsflaechen Rollstuhl barrierefreies Bauen Flurbreite Tuerbreite Untersuchung', '["TERM-002","TERM-021"]', 'consensus', 'scoping', NULL, 10, 10, 2, 'none', NULL, NULL, 0, 'session_2026-09-02-research-batch-05-circulation-icf', '2026-09-02 21:08', 'Highest-yield search of the batch. HONESTY NOTE from the retrieving agent: Consensus is a semantically English-centric index, so a German query returned English-language results. The QUERY was non-English; the INDEX was not. That is why a genuine national-language index was queried separately.  R7 HARM FINDING: Code-compliant space fails between 10 and 100 percent of wheeled-mobility users depending on the manoeuvre.', 1);
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "session", "executed_at", "findings_note", "harm_finding") VALUES (40, 'accessible-circulation-geometry', NULL, 'EN', 3, 'clinical', 'intrinsic', '(wheelchair OR "mobility scooter" OR "walking aid") AND (injury OR fall OR entrapment OR trauma) AND (door OR elevator OR lift OR threshold OR ramp OR "level change") AND (building OR indoor OR "built environment" OR home)', '["TERM-022","TERM-079"]', 'pubmed', 'scoping', NULL, 45, 7, 0, 'none', NULL, NULL, 0, 'session_2026-09-02-research-batch-05-circulation-icf', '2026-09-02 21:08', 'R14 QUERY-SHAPE FAILURE, kept. MeSH expanded lift to "lifting"[MeSH], fall to Accidental Falls and trauma to Wounds and Injuries, returning dry-beriberi physiotherapy, a brain-computer-interface door opener and spinal-cord-injury fracture epidemiology. 1 of 7 on-topic. The R7 harm class is not reachable from PubMed by AND-chaining these concepts.', 0);
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "session", "executed_at", "findings_note", "harm_finding") VALUES (41, 'accessible-circulation-geometry', NULL, 'JA', 3, 'clinical', 'intrinsic', '車椅子 廊下 幅員 (J-STAGE WebAPI, api.jstage.jst.go.jp/searchapi/do?service=3)', '["TERM-002"]', 'registry', 'scoping', NULL, 49, 20, 0, 'none', NULL, NULL, 0, 'session_2026-09-02-research-batch-05-circulation-icf', '2026-09-02 21:08', 'THE R5 FINDING OF THE BATCH. 49 Japanese academic papers on wheelchair x corridor x width in one national index; English-language engines surfaced one of them. Independently re-found the Baba 2004 admission as hit 2, which is cross-index corroboration rather than a second admission. R5: this is peer-reviewed academic work and its non-indexation in English databases is an INDEXING fact, not an evidence-quality fact.', 0);
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "session", "executed_at", "findings_note", "harm_finding") VALUES (42, 'accessible-circulation-geometry', NULL, 'EN', NULL, NULL, NULL, '[NOT SEARCHED] vertical circulation as a sub-construct: passenger lifts, platform lifts, evacuation lifts', NULL, 'none', 'scoping', NULL, 0, 0, 0, NULL, NULL, 'DELIBERATELY NOT SEARCHED, and not for want of budget. Vertical circulation is the one part of this slug whose determinative literature is standards-and-conformity (EN 81-70, EN 81-41, ISO 21542, ASME A18.1) rather than measured human demand, and the 2026-08-12 REFERENCE-ONLY ruling means those documents may be NAMED as leads but not mined for values. An evidence search here would have produced a list of standards that cannot be quoted plus a thin scatter of entrapment case reports - high cost, near-zero admissible yield, and a standing risk of smuggling a code value into a research row. NO CLAIM IS MADE ABOUT LIFT DIMENSIONS. The owed action is a research_code_leads pass, which is a different activity from an evidence search.', 0, 'session_2026-09-02-research-batch-05-circulation-icf', '2026-09-02 21:08', NULL, 0);
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "session", "executed_at", "findings_note", "harm_finding") VALUES (43, 'accessible-circulation-geometry', 'GB', 'EN', 1, 'co1', 'intrinsic', 'euansguide.com site walk: homepage -> /accesssurvey -> report PDF on the charity S3 (R10 re-retrieval of the C-13 lead after exec 34 logged a 404)', NULL, 'web', 'scoping', NULL, 5, 5, 1, 'none', NULL, NULL, 0, 'session_2026-09-02-research-batch-05-circulation-icf', '2026-09-02 21:29', 'R10 re-retrieval: a 404 is not a terminal answer. exec 34 tried euansguide.com/files/final-23-euansguide-results-pdf.pdf and received a Page-not-found page (logged 72c0fcb12f42614c.html, 15580 B). Four further fetches were logged; the homepage carries a link to /accesssurvey, which carries the live report on the charity S3. Retrieved f07d3924aaec6708.pdf, 3344268 B, 29 pp, sha256 f07d3924aaec6708a1246c6e545fb8c9c7927f9c79f230cd3b225c2e79daa940. HARM FINDING (R7): the most-cited barrier in the survey is Q7 option 2, could not get around the venue (lack of lifts, narrow corridors, too little space or poor layout), at 56 percent - ahead of could not get into the venue at 41 percent (p.13). Among 4400+ disabled respondents, circulation geometry is the most-reported failure class, and it outranks the entrance-focused barrier that accessibility practice most often addresses. || CORRECTED 2026-09-02: R15 applied to my own writing: the ranking as first recorded OVER-CLAIMED. Full option set of Q7 (p.13-14) is parking 64, could-not-get-around-the-venue 56, could-not-participate 45, could-not-get-into-the-venue 41, no-suitable-toilet 41, staff-attitudes 34, facilities-not-as-expected 32, environment-uncomfortable 28, no-accessible-transport 22, staff-unsure-of-equipment 15, other 8, no-alternative-formats 4. So circulation geometry is NOT the most-cited barrier in the survey: parking at 64 percent outranks it. The defensible claim is that it is the most-cited IN-BUILDING barrier and second overall, ahead of entrance access and of accessible toilets which tie at 41 percent. Corrected before this batch reached canonical. || CORRECTED 2026-09-02: TWO CORRECTIONS TO THIS ROW''S OWN TEXT. (a) It says ''Among 4400+ disabled respondents''. The report says ''Over 4,400 people''; Q1 (p.11, multi-select) reports 88 percent completing as a disabled person and the remainder as family or friend 13, unpaid or family carer 9, carer or PA 2, retirement age 11, professional 1, other 1. So: over 4,400 respondents, 88 percent of them disabled people, not 4,400+ disabled respondents. The population-match rows state this correctly; this row did not. (b) THE FETCH COUNT IS UNDERSTATED. results_found=5 and the note''s ''four further fetches'' are both wrong. The manifest holds SEVEN euansguide fetches for this lead: the original 404 logged by exec 34, then SIX further - /access-survey/, the homepage, /news/access-survey/, /access-survey-results/, /accesssurvey, and the report PDF. The ''five'' in the commit message of the same hour is wrong for the same reason. results_found is an integer on an append-only log and this writer does not touch it; the correct figure is six further fetches, and it is stated here rather than silently rewritten there.', 1);
INSERT INTO "search_admissions" ("exec_id", "ref_id", "created_at", "created_by_session") VALUES (32, 'REF-00975', '2026-09-02 21:08', 'session_2026-09-02-research-batch-05-circulation-icf');
