INSERT INTO "search_admissions" ("exec_id", "ref_id", "created_at", "created_by_session") VALUES (39, 'REF-00976', '2026-09-02 21:08', 'session_2026-09-02-research-batch-05-circulation-icf');
INSERT INTO "search_admissions" ("exec_id", "ref_id", "created_at", "created_by_session") VALUES (43, 'REF-00978', '2026-09-02 21:29', 'session_2026-09-02-research-batch-05-circulation-icf');
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "session", "created_at") VALUES (61, NULL, 'accessible-circulation-geometry', NULL, 'PENDING-VERIFICATION', '(En)Abling Architectural Research: Co-Designing With People With Intellectual Disabilities', '10.1111/jar.70275', 'RESOLVED', 1, 0, 'Reports method, not buildings, so it carries no circulation-geometry content for this slug.', 'HIGHEST-VALUE STAGED ITEM. The strongest Co-1 warrant found in this batch and it is VERIFIABLE, not hypothesised: co-author Zarah Kaleem is affiliated to Cardiff People First, a self-advocacy organisation, and the abstract states the article is co-authored by academic researchers and a co-researcher with lived experience of an intellectual disability - quoted from retrieved full text. OWED ACTION IS SPECIFIC: retrieve the underlying Cardiff University doctoral study (Welsh School of Architecture, ethics refs SREC 2204, 22111, 23048), which the paper says generated concrete, participant-led insights about sensory, spatial and navigational challenges. That is where the ID / AX-COG-O / AX-SPR circulation evidence lives.', 'session_2026-09-02-research-batch-05-circulation-icf', '2026-09-02 21:10');
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "session", "created_at") VALUES (62, NULL, 'accessible-circulation-geometry', NULL, 'PENDING-VERIFICATION', 'WALKING BEHAVIOR OF A CROWD INCLUDING WHEELCHAIR USERS (Tsuchiya, Furukawa, Miyano, Yoshida, Hasemi 2003, AIJ)', '10.3130/aije.68.1_6', 'RESOLVED', 3, 0, 'Only the title is confirmed; contents unread.', 'PRIOR ART BY SIXTEEN YEARS to the paper batch 04 called its single highest-value staged item (Geoerg 2019, crowd flow with wheelchair users). Japanese-language, AIJ, invisible to every English engine run this session. HYPOTHESIS that it contains quantified flow or width data - only the title is held. If it does, the English-language crowd-dynamics literature has been rediscovering a 2003 result. Requires a Japanese reader.', 'session_2026-09-02-research-batch-05-circulation-icf', '2026-09-02 21:10');
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "session", "created_at") VALUES (63, NULL, 'accessible-circulation-geometry', NULL, 'PENDING-VERIFICATION', 'Anthropometric data for wheelchair users: a systematic literature review (Braganca et al.)', '10.1080/10803548.2019.1567974', 'RESOLVED', 2, 0, 'Could not confirm risk-of-bias appraisal or effect synthesis, and tier-system 9 makes that the difference between T2 sr_meta and T3. Taylor and Francis returned 403.', 'THE INADEQUACY ANCHOR IF IT SURVIVES ONE TEST. Its finding is that wheelchair-user anthropometry - the data under every dimensional standard - is limited, with a lack of consistency between studies regarding measurements collected, samples used and methods applied, across 41 articles. THE FALSIFICATION TEST IS ONE SENTENCE LONG: does the method section contain a quality appraisal? Yes gives T2 and a strong admission; no gives T3 mapping review. Deliberately NOT admitted rather than guessed.', 'session_2026-09-02-research-batch-05-circulation-icf', '2026-09-02 21:10');
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "session", "created_at") VALUES (64, NULL, 'accessible-circulation-geometry', NULL, 'REHOME', 'Revisiting Clear Floor Area Requirements for Wheeled Mobility Device Users in Public Transportation (Bharathy & D Souza 2018)', '10.1177/0361198118787082', 'RESOLVED', 1, 0, 'Setting is transportation vehicles, so on-construct for footprint but off-setting for buildings.', 'n=500 wheeled-mobility users, the updated IDeA Center dataset. Abstract states prior research indicates standard clear-floor dimensions are too small to accommodate many occupied wheeled mobility devices, especially power chairs and scooters. Batch 04 staged the same paper; NOT re-verified through Crossref this session, so treat its bibliography as unconfirmed.', 'session_2026-09-02-research-batch-05-circulation-icf', '2026-09-02 21:10');
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "session", "created_at") VALUES (65, NULL, 'accessible-circulation-geometry', NULL, 'PENDING-VERIFICATION', 'Space Requirements for Wheeled Mobility Devices in Public Transportation (D Souza, Steinfeld, Paquet, Feathers 2010)', '10.3141/2145-08', 'RESOLVED', 1, 0, 'Tier is contested by the project record and must not be inherited.', 'n=369, the earlier IDeA dataset that the 2018 paper supersedes. Batch 04 admitted this as T1 and its own repair plan records that the T1 was asserted on the same test the brief used to put another paper at T3. DO NOT INHERIT THAT TIER - re-argue it. R9: not held.', 'session_2026-09-02-research-batch-05-circulation-icf', '2026-09-02 21:10');
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "session", "created_at") VALUES (66, NULL, 'accessible-circulation-geometry', NULL, 'PENDING-VERIFICATION', 'Anthropometry and Standards for Wheeled Mobility: An International Comparison (Steinfeld et al. 2010)', NULL, NULL, 2, 0, 'No DOI resolved and the author list is unusable.', 'Compares four countries research against their prevailing standards; abstract states US standards are based on research conducted in the 1970s and need to be updated. HYPOTHESIS on all bibliographic detail - the Consensus rendering gave only "E. Steinfeld et al." and NOTHING beyond the first author should be stored from it.', 'session_2026-09-02-research-batch-05-circulation-icf', '2026-09-02 21:10');
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "session", "created_at") VALUES (67, NULL, 'accessible-circulation-geometry', NULL, 'MISCELLANEOUS', 'Thies et al. 2023, BMC Geriatrics 23(1):734 - walking-frame development trial', '10.1186/s12877-023-04443-7', 'RESOLVED', 3, 1, 'The usable line is background, attributed to prior work - a citation of a citation.', 'Carries the one usable line from the harm search: lifting of walking frames when crossing door thresholds or when turning has shown to reduce stability, and certain design features drive the need to lift. That is a threshold-harm mechanism for AX-BAL and AX-AMB. MINE THE REFERENCE BEHIND THAT SENTENCE; do not cite this paper for it. The study itself is a walking-frame trial with 9 healthy older adults and 9 frame users.', 'session_2026-09-02-research-batch-05-circulation-icf', '2026-09-02 21:10');
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "session", "created_at") VALUES (68, NULL, 'accessible-circulation-geometry', NULL, 'PENDING-VERIFICATION', 'Measuring spatial accessibility for wheelchair users: a case study in a Chinese campus (Huang et al. 2025)', '10.1371/journal.pone.0335663', 'RESOLVED', 3, 0, 'Sample may be simulation rather than disabled participants.', 'Reports mean travel speed 1.03 m/s assisted versus 0.67 m/s unassisted, and that unassisted users could not pass curb ramps steeper than 1:5. WARNING: the abstract says thirty students with wheelchair experience, which may mean able-bodied students IN wheelchairs, i.e. simulation, which is PROXY at best under R13. Resolve before use. HYPOTHESIS on the full author list - store nothing beyond the first author. Batch 04 staged the same paper with the same warning.', 'session_2026-09-02-research-batch-05-circulation-icf', '2026-09-02 21:10');
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "session", "created_at") VALUES (69, NULL, 'accessible-circulation-geometry', NULL, 'MISCELLANEOUS', 'Improving the built environment for manual wheelchair users: A review (Flemmer 2022)', NULL, NULL, 3, 0, 'Narrative review, so T3 under tier-system 9 and never sr_meta.', 'Useful for its three-part framing - intrinsic capability, non-compliant features, maintenance and obstruction - which maps cleanly onto the ICF person-environment split. Not an anchor.', 'session_2026-09-02-research-batch-05-circulation-icf', '2026-09-02 21:10');
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "session", "created_at") VALUES (70, NULL, 'accessible-circulation-geometry', NULL, 'PENDING-VERIFICATION', 'Wheelchair-Accessibility of Religious Places of Worship in Anambra State, Nigeria (Akosile et al. 2025)', NULL, NULL, 3, 1, 'Authorship and DOI not resolved.', 'Cross-sectional audit of 193 buildings reporting 94.3pc of doorways and 94.8pc of routes accessible but only 4.2pc of ramps and 10.2pc of steps, and 0 of 61 buildings needing lifts had one - overall 3.6pc accessible. CORRECTS THE HIGH-INCOME SKEW that the admitted systematic review names as its own limitation. HYPOTHESIS on full authorship and DOI. Note its accessibility criterion is ADAAG conformity, which the batch harm finding shows is not itself a usability criterion.', 'session_2026-09-02-research-batch-05-circulation-icf', '2026-09-02 21:10');
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "session", "created_at") VALUES (71, NULL, 'accessible-circulation-geometry', NULL, 'REHOME', 'Urban Chandelier: How Experiences of Being Vision Impaired Inform Designing for Attentiveness (Liebergesell, Vermeersch, Heylighen 2021)', '10.1111/joid.12192', 'RESOLVED', 3, 0, 'Belongs to a wayfinding or sensory slug rather than circulation geometry.', 'Heylighen group work, which proceeds from disabled people spatial expertise. HYPOTHESIS that it contains circulation-geometry content. Relevant to AX-VIS-L and AX-VIS-N.', 'session_2026-09-02-research-batch-05-circulation-icf', '2026-09-02 21:10');
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "session", "created_at") VALUES (72, NULL, 'accessible-circulation-geometry', NULL, 'PENDING-VERIFICATION', 'Japanese seam tail: Osakaya 1999 (10.3130/aijt.5.139) and Baba et al. 2002 (10.3130/aija.67.121_3), plus ~45 further J-STAGE records unexamined', NULL, NULL, 3, 0, 'Bulk lead; individual records not appraised.', 'The tail of the 49-record Japanese seam. The 2002 Baba paper is A PROPOSAL ON EVALUATION METHOD FOR LIFETIME HOMES BASED ON BUILDING STANDARDS IN UNITED KINGDOM - a Japanese team evaluating UK Lifetime Homes standards, a cross-jurisdictional appraisal invisible to UK-language search. Both DOIs Crossref-verified this session.', 'session_2026-09-02-research-batch-05-circulation-icf', '2026-09-02 21:10');
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "session", "created_at") VALUES (73, NULL, 'accessible-circulation-geometry', NULL, 'ADMITTED', 'Euan s Guide Access Survey (Euan s Guide, Scottish charity SC045492, disability-led)', NULL, NULL, 2, 0, 'The 2023 report URL returns HTML rather than the PDF, so the document itself was never retrieved.', 'Genuinely disability-led with a decade of annual survey data and 6000+ respondents in 2023. Content skews to information provision, toilets and staff attitude rather than circulation. RETRIEVE THE ACTUAL PDF BEFORE JUDGING IT; if its circulation content is thin, say so and close it rather than leaving it open indefinitely. || RESOLVED 2026-09-02 (R15, re-described from the source; admitted as REF-00978): Retrieved in full (f07d3924aaec6708.pdf, 29 pp, published March 2026). Both halves of the staged description above are wrong. The respondent count is over 4,400, not 6,000+, and the report is the 2025 survey, not 2023. The content claim is false: Q7, barriers commonly found when out and about (p.13-14), ranks lack of appropriate parking 64 percent, could not get around the venue for want of lifts, corridor width, space or layout 56 percent, could not participate in the same way 45 percent, could not get into the venue 41 percent, no suitable toilet 41 percent, staff attitudes 34 percent. Circulation geometry is the most-cited in-building barrier and second of twelve overall, ahead of both the entrance and toilet options the staged description named it as skewing towards. The staged text was written from a Page-not-found page and no retrieved payload ever supported it. Q1 (p.11): 88 percent of respondents are disabled people; the survey asks no impairment-type question, so no population is separable and every figure is whole-sample.', 'session_2026-09-02-research-batch-05-circulation-icf', '2026-09-02 21:10');
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "session", "created_at") VALUES (74, NULL, 'accessible-circulation-geometry', NULL, 'PENDING-VERIFICATION', 'Accessibility of public buildings in the United States: a cross-sectional survey (Disability and Society)', '10.1080/09687599.2023.2239996', 'RESOLVED', 3, 0, 'No Crossref lookup was run; authors and year unconfirmed.', 'n=109 disabled respondents on BUILDINGS rather than streets, largely reporting on accessibility barriers encountered in communal spaces. HYPOTHESIS on authors, year and all content - NOTHING beyond the DOI and title should be stored. R9: not held.', 'session_2026-09-02-research-batch-05-circulation-icf', '2026-09-02 21:10');
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "session", "created_at") VALUES (75, NULL, 'accessible-circulation-geometry', NULL, 'PENDING-VERIFICATION', 'Backward citation mining targets: the reference lists of the three strongest anchors plus the 41 studies included in the Braganca review', NULL, NULL, NULL, 0, 'A mining target rather than a source.', 'Backward citation mining on the anchors is the single cheapest next action: three papers, one lab lineage plus the IDeA Center lineage, and between them they cover every manoeuvre primitive in the slug.', 'session_2026-09-02-research-batch-05-circulation-icf', '2026-09-02 21:10');
INSERT INTO "evidence_population_match" ("match_id", "source_ref", "target_population", "study_population", "sample_size", "match_grade", "mismatch_note", "created_at", "created_by_session", "ref_id", "gap_id") VALUES ('session_2026-09-02-resea-REF-00784-MOB', 'REF-00784', 'MOB', 'MWC 109 / PWC 100 / scooter 14, adults, both sexes', 223, 'EXACT', 'Convenience sample recruited partly at a national wheelchair sport event, so likely skewed toward younger, fitter, more skilled users. That skew biases the finding CONSERVATIVELY: a more able sample failing code-compliant space understates the failure rate. Diagnosis not reported, so MS, PAIN and LMB cannot be graded separately.', '2026-09-02 21:10', 'session_2026-09-02-research-batch-05-circulation-icf', 'REF-00784', NULL);
INSERT INTO "evidence_population_match" ("match_id", "source_ref", "target_population", "study_population", "sample_size", "match_grade", "mismatch_note", "created_at", "created_by_session", "ref_id", "gap_id") VALUES ('session_2026-09-02-resea-REF-00784-SCI', 'REF-00784', 'SCI', 'wheeled-mobility device users, diagnosis not reported', 223, 'PARTIAL', 'SCI is not separable in the reported sample: the study grades by device type, not diagnosis.', '2026-09-02 21:10', 'session_2026-09-02-research-batch-05-circulation-icf', 'REF-00784', NULL);
INSERT INTO "evidence_population_match" ("match_id", "source_ref", "target_population", "study_population", "sample_size", "match_grade", "mismatch_note", "created_at", "created_by_session", "ref_id", "gap_id") VALUES ('session_2026-09-02-resea-REF-00971-MOB', 'REF-00971', 'MOB', 'five scooters operated by ONE expert driver; no scooter user participated', 1, 'PROXY', 'The human operator is an expert and, undeclared but implied, non-disabled. All user-side variance is absent - strength, trunk control, reach, spasticity, visual field, cognition, fatigue, confidence. It measures what a DEVICE can do, not what a PERSON can do. LPA, BAR, LMB and VES are entirely unrepresented.', '2026-09-02 21:10', 'session_2026-09-02-research-batch-05-circulation-icf', 'REF-00971', NULL);
INSERT INTO "evidence_population_match" ("match_id", "source_ref", "target_population", "study_population", "sample_size", "match_grade", "mismatch_note", "created_at", "created_by_session", "ref_id", "gap_id") VALUES ('session_2026-09-02-resea-REF-00972-MOB', 'REF-00972', 'MOB', 'as part I: expert driver, two scooter models', 1, 'PROXY', 'As part I, and additionally n=2 devices, so device-model variance is barely sampled. Not independent of REF-00971: same lab, same five authors, same driver, same method.', '2026-09-02 21:10', 'session_2026-09-02-research-batch-05-circulation-icf', 'REF-00972', NULL);
INSERT INTO "evidence_population_match" ("match_id", "source_ref", "target_population", "study_population", "sample_size", "match_grade", "mismatch_note", "created_at", "created_by_session", "ref_id", "gap_id") VALUES ('session_2026-09-02-resea-REF-00973-MOB', 'REF-00973', 'MOB', '17 people with SCI using manual wheelchairs', 17, 'PARTIAL', 'SCI-only sample; does not speak for ambulant or non-SCI wheeled-mobility users.', '2026-09-02 21:10', 'session_2026-09-02-research-batch-05-circulation-icf', 'REF-00973', NULL);
INSERT INTO "evidence_population_match" ("match_id", "source_ref", "target_population", "study_population", "sample_size", "match_grade", "mismatch_note", "created_at", "created_by_session", "ref_id", "gap_id") VALUES ('session_2026-09-02-resea-REF-00973-SCI', 'REF-00973', 'SCI', '17 people with SCI, C4-T12, AIS A/B/C, MWC >4h/day, 16 men 1 woman, mean age 39.8', 17, 'EXACT', 'TWO MISMATCHES AND THE FIRST IS SEVERE. (i) Inclusion criteria require independent community mobility in the MWC INCLUDING ASCENDING AN ACCESS RAMP, so the study structurally SELECTS OUT exactly the people for whom ramps are already impassable; the finding is a lower bound on population burden. (ii) 16 of 17 participants are men, and shoulder anthropometry and strength are sexually dimorphic, so this cannot ground a claim about women wheelchair users.', '2026-09-02 21:10', 'session_2026-09-02-research-batch-05-circulation-icf', 'REF-00973', NULL);
INSERT INTO "evidence_population_match" ("match_id", "source_ref", "target_population", "study_population", "sample_size", "match_grade", "mismatch_note", "created_at", "created_by_session", "ref_id", "gap_id") VALUES ('session_2026-09-02-resea-REF-00974-MOB', 'REF-00974', 'MOB', 'ten able-bodied participants', 10, 'PROXY', 'Stated plainly: NO WHEELCHAIR USER TOOK PART. Able-bodied participants have intact trunk control, no shoulder overuse history, no SCI-related muscle imbalance and no chronic exposure - they lack the very condition the study exists to inform. The absolute forces are indicative only; the RANKING across activities is the transferable part, and even that is a hypothesis for real users.', '2026-09-02 21:10', 'session_2026-09-02-research-batch-05-circulation-icf', 'REF-00974', NULL);
INSERT INTO "evidence_population_match" ("match_id", "source_ref", "target_population", "study_population", "sample_size", "match_grade", "mismatch_note", "created_at", "created_by_session", "ref_id", "gap_id") VALUES ('session_2026-09-02-resea-REF-00975-MOB', 'REF-00975', 'MOB', '145 respondents: 112 people with mobility impairment plus 33 family members', 145, 'PARTIAL', 'TWO WRITTEN MISMATCHES. (i) 22.7 percent of responses are PROXY VOICE - a carer or relative answering on behalf of the disabled person; under a Co-1 reading that alone would disqualify, under T3 it is a stated limitation. (ii) Australia-only, over-represents severe and profound impairment against a 2.9 percent population base rate, and over-represents under-65s. NOT graded for BLIND, DEAF, AUT, ID or DEM: those populations were not sampled.', '2026-09-02 21:10', 'session_2026-09-02-research-batch-05-circulation-icf', 'REF-00975', NULL);
INSERT INTO "evidence_population_match" ("match_id", "source_ref", "target_population", "study_population", "sample_size", "match_grade", "mismatch_note", "created_at", "created_by_session", "ref_id", "gap_id") VALUES ('session_2026-09-02-resea-REF-00975-PAIN', 'REF-00975', 'PAIN', 'arthritis 28.9pc, back problems 28.3pc, knee problems 24.1pc', 145, 'PARTIAL', 'Pain conditions are the most common reported impairments but the study measures housing accessibility, not pain response; the crossing is inferential.', '2026-09-02 21:10', 'session_2026-09-02-research-batch-05-circulation-icf', 'REF-00975', NULL);
INSERT INTO "evidence_population_match" ("match_id", "source_ref", "target_population", "study_population", "sample_size", "match_grade", "mismatch_note", "created_at", "created_by_session", "ref_id", "gap_id") VALUES ('session_2026-09-02-resea-REF-00976-MOB', 'REF-00976', 'MOB', 'field survey of newly built Japanese residences - dwellings, not people', 0, 'PROXY', 'The unit of analysis is a BUILDING, not a person. Wheelchair movement is assessed as a geometric possibility, never observed. Japanese dwelling stock and Japanese body and device dimensions may not transfer. Grade is provisional on the English abstract only, per R15.', '2026-09-02 21:10', 'session_2026-09-02-research-batch-05-circulation-icf', 'REF-00976', NULL);
INSERT INTO "evidence_population_match" ("match_id", "source_ref", "target_population", "study_population", "sample_size", "match_grade", "mismatch_note", "created_at", "created_by_session", "ref_id", "gap_id") VALUES ('session_2026-09-02-resea-REF-00977-MOB', 'REF-00977', 'MOB', 'synthesis of 48 studies of mobility assistive device users', 48, 'PARTIAL', 'The review states its own limitation: the reviewed studies mostly focused on wheelchair users residing in high-income countries. The synthesis therefore inherits a high-income, wheelchair-centric skew and does not speak for LMB, LPA, BAR or the Global South.', '2026-09-02 21:10', 'session_2026-09-02-research-batch-05-circulation-icf', 'REF-00977', NULL);
INSERT INTO "evidence_population_match" ("match_id", "source_ref", "target_population", "study_population", "sample_size", "match_grade", "mismatch_note", "created_at", "created_by_session", "ref_id", "gap_id") VALUES ('session_2026-09-02-resea-REF-00978-ALL', 'REF-00978', 'ALL', 'UK-wide self-selecting online survey, over 4,400 respondents. Q1 (p.11), multi-select: a disabled person 88%, family member or friend 13%, unpaid or family carer 9%, carer or PA 2%, someone of retirement age 11%, teacher/social worker/healthcare professional 1%, someone else 1%.', 4400, 'PARTIAL', 'THE SURVEY ASKS NO IMPAIRMENT-TYPE QUESTION, so no population is separable from the sample and every percentage is whole-sample. That is why the target is ALL and the grade is PARTIAL rather than EXACT: the source can say that 56% of a large disabled sample commonly meet in-building circulation barriers, and cannot say which populations carry that 56%. Roughly 12% of responses come from proxies (family, carer, PA, professional) rather than disabled people themselves, and the instrument does not let proxy responses be excluded from the barrier percentages. Self-selection through a disabled-access charity''s own channels biases toward people who already encounter and report access barriers; the direction inflates prevalence and does not affect the RANKING of barriers against each other, which is what this source is admitted for.', '2026-09-02 21:34', 'session_2026-09-02-research-batch-05-circulation-icf', 'REF-00978', NULL);
INSERT INTO "evidence_population_match" ("match_id", "source_ref", "target_population", "study_population", "sample_size", "match_grade", "mismatch_note", "created_at", "created_by_session", "ref_id", "gap_id") VALUES ('session_2026-09-02-resea-REF-00978-MOB', 'REF-00978', 'MOB', 'Mobility-device use is reported only indirectly, via Q29 main modes of transport (p.22), multi-select: wheelchair 25%, mobility scooter 24%, powerchair 15%, wheelchair with a power attachment 6%, walking 12%, car owned or leased 91%.', 4400, 'PARTIAL', 'Q29 is a transport question, not an impairment question, and it is NOT cross-tabulated against the Q7 barriers question. So mobility-device users are demonstrably a large share of the sample, but the 56% could-not-get-around-the-venue figure cannot be attributed to them specifically - it is the whole-sample figure. Graded PARTIAL for that reason. Using this source to anchor a MOB-specific value would assert a cross-tabulation the report does not publish.', '2026-09-02 21:34', 'session_2026-09-02-research-batch-05-circulation-icf', 'REF-00978', NULL);
INSERT INTO "evidence_population_match" ("match_id", "source_ref", "target_population", "study_population", "sample_size", "match_grade", "mismatch_note", "created_at", "created_by_session", "ref_id", "gap_id") VALUES ('session_2026-09-02-resea-REF-00978-MOB-2', 'REF-00978', 'MOB', 'DISSENTING SECOND ROW (adversarial pass, 2026-09-02). Same sample as the PARTIAL row on this ref; the disagreement is about what the sample can carry, not about who was in it.', 4400, 'PROXY', 'The PARTIAL row on this ref asserts that self-selection ''does not affect the RANKING of barriers against each other, which is what this source is admitted for.'' That claim is unevidenced and is most likely wrong in a specific direction. On the face of the report: the survey is supported by the Motability Scheme (p.3), Motability Operations supplies two of three pull-quotes and an About page (pp.9-10), Q29 reports ''Car - owned or leased'' at 91 percent (p.22), and the top-ranked barrier at Q7 is ''A lack of appropriate parking available'' at 64 percent (p.14) - the sponsor''s own domain. A sample that is 91 percent car-owning, recruited through a disabled-access charity co-branded with a car-lease scheme, is precisely the recruitment that would inflate the parking option relative to the others. The report publishes NO methodology - no sampling method, no fieldwork dates, no per-question base, no weighting anywhere in 29 pages - so sponsor-channel recruitment can be neither confirmed nor excluded, which is why this is graded PROXY rather than left implicit. WHAT SURVIVES: the in-building comparison this source is actually used for - could not get around the venue 56 percent against could not get into the venue 41 percent and no suitable toilet 41 percent - is between three options none of which is the sponsor''s domain, and is not touched by the parking argument. WHAT DOES NOT: any use of the whole-question ranking, including any statement that parking is the leading barrier for disabled people.', '2026-09-02 21:51', 'session_2026-09-02-research-batch-05-circulation-icf', 'REF-00978', NULL);
