INSERT INTO "citation_mining" ("slug", "local_ref_id", "global_ref_id", "doi", "backward", "forward", "connections_produced", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "deferred_reason") VALUES ('accessible-circulation-geometry', 'ACG-08', 'REF-00977', NULL, 1, 0, '["10.1001/jama.299.3.332", "10.1002/9781119536604", "10.1007/978-3-319-31416-7_14", "10.1007/s10708-018-9907-y", "10.1007/s13670-019-00295-5", "10.1007/s40520-015-0410-8", "10.1016/j.aap.2021.106259", "10.1016/j.alter.2015.11.003", "10.1016/j.apergo.2014.01.002", "10.1016/j.apmr.2008.05.011", "10.1016/j.apmr.2010.01.009", "10.1016/j.apmr.2011.01.008", "10.1016/j.cities.2007.01.009", "10.1016/j.dhjo.2019.100844", "10.1016/j.ergon.2014.07.001", "10.1016/j.ijtst.2018.04.005", "10.1016/j.jemermed.2007.07.067", "10.1016/j.jth.2020.100975", "10.1016/j.medengphy.2009.01.004", "10.1016/j.medengphy.2009.07.022", "10.1016/j.tra.2018.02.017", "10.1017/s0144686x18001228", "10.1038/sc.2015.26", "10.1057/s41289-018-0070-3", "10.1080/01441647.2020.1747569", "10.1080/01616846.2010.502033", "10.1080/03081060.2016.1266165", "10.1080/09638280500052799", "10.1080/09687590025775", "10.1080/09687590220140377", "10.1080/09687599.2012.631797", "10.1080/09687599.2018.1453783", "10.1080/10400430903520280", "10.1080/10400435.2010.541408", "10.1080/10400435.2012.659326", "10.1080/13602365.2019.1684974", "10.1080/13604810801933495", "10.1080/14616688.2017.1293721", "10.1080/15389588.2019.1606910", "10.1080/17483100802542603", "10.1080/17483100802543247", "10.1080/17483107.2017.1312573", "10.1080/17483107.2017.1401128", "10.1080/17483107.2019.1604824", "10.1080/23748834.2017.1316025", "10.1080/23748834.2018.1429180", "10.1089/jwh.2015.5385", "10.1097/phm.0b013e31818a52cc", "10.1111/ijcs.12155", "10.1136/injuryprev-2015-041805", "10.1145/2875452", "10.1177/0018720812460549", "10.1177/0038038503037002002", "10.1177/0265813515617659", "10.1177/0361198120922995", "10.1186/1743-0003-9-20", "10.1201/b1