INSERT INTO "citation_mining" ("slug", "local_ref_id", "global_ref_id", "doi", "backward", "forward", "connections_produced", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "deferred_reason") VALUES ('accessible-circulation-geometry', 'ACG-09', 'REF-00978', NULL, 1, 0, '[]', NULL, '2026-09-02 22:02', 'session_2026-09-02-research-batch-05-circulation-icf', '2026-09-02 22:02', 'session_2026-09-02-research-batch-05-circulation-icf', 'Not mineable, and not deferred for effort. The Euan''s Guide Access Survey is a 29-page grey report of the charity''s own survey: it carries no reference list, no bibliography and no citations of any kind (checked across all 29 pages of the retrieved PDF f07d3924aaec6708.pdf). Backward mining has nothing to walk and forward mining would return citations OF a non-indexed grey report. Recorded as not-applicable rather than left pending, so a reader can tell ''nothing to mine'' from ''not yet mined''.');